import type { TargetAndTransition } from 'motion-v'
import { blur, ease } from '@animate-ui/vue/utils/motion'

export type PageTransitionEffect =
  | 'fade'
  | 'slide'
  | 'push'
  | 'zoom'
  | 'iris'
  | 'wipe'
  | 'bands'
  | 'stack'
  | 'flow'
  | 'chop'
  | 'random';

export type Effect = Exclude<PageTransitionEffect, 'random'>;

export type Frame = {
  width: number;
  top: number;
  bottom: number;
  x: number;
  y: number;
};

type EffectAnimation = {
  enter: TargetAndTransition;
  exit: TargetAndTransition;
};

const SLIDE = 60;
const BANDS = 5;
const BAND_STAGGER = 0.12;
const BAND_FRAMES = 16;

const still = (duration: number): TargetAndTransition => ({
  transform: ['none', 'none'],
  transition: { duration },
});

const easeOutCubic = (t: number) => 1 - (1 - t) ** 3;

function bandFrames(back: boolean, { top, bottom }: Frame) {
  const span = 1 - (BANDS - 1) * BAND_STAGGER;
  return Array.from({ length: BAND_FRAMES + 1 }, (_, frame) => {
    const t = frame / BAND_FRAMES;
    const points: string[] = [];
    for (let band = 0; band < BANDS; band++) {
      const progress = easeOutCubic(
        Math.min(1, Math.max(0, (t - band * BAND_STAGGER) / span)),
      );
      const edge = back ? 100 : 0;
      const reach = back ? 100 - progress * 100 : progress * 100;
      const from = top + ((bottom - top) * band) / BANDS;
      const to = top + ((bottom - top) * (band + 1)) / BANDS;
      points.push(
        `${edge}% ${from}px`,
        `${reach}% ${from}px`,
        `${reach}% ${to}px`,
        `${edge}% ${to}px`,
      );
    }
    return `polygon(${points.join(', ')})`;
  });
}

export const CLIP =
  ':root[data-page-transition]::view-transition-old(root){display:none}:root[data-page-transition]::view-transition-new(root){animation:none}' +
  '::view-transition-image-pair(*.page-transition){overflow:clip}' +
  '::view-transition-group(*.page-transition-shared){z-index:1;overflow:clip}' +
  '::view-transition-old(*.page-transition-shared),::view-transition-new(*.page-transition-shared){height:100%;object-fit:cover}';

export const SHARE = { duration: 0.45, ease: ease.resize };

export const radii = new Map<string, string>();

// Only a page change hides the old page: other view transitions (a theme
// switch) keep theirs.
let marks = 0

export function markRoot() {
  const root = document.documentElement
  const mark = ++marks
  root.setAttribute('data-page-transition', '')
  const transition = (
    document as Document & { activeViewTransition?: ViewTransition | null }
  ).activeViewTransition
  const done = transition
    ? transition.finished
    : new Promise(resolve => requestAnimationFrame(resolve)).then(() =>
        Promise.all(
          root
            .getAnimations({ subtree: true })
            .filter(animation =>
              (animation.effect as KeyframeEffect | null)?.pseudoElement?.startsWith('::view-transition'),
            )
            .map(animation => animation.finished),
        ),
      )
  void done
    .catch(() => {})
    .finally(() => {
      if (mark === marks)
        root.removeAttribute('data-page-transition')
    })
}

export function morphRadius(name: string, from: string | undefined, to: string) {
  if (!from || from === to) return;
  const animation = document.documentElement.animate(
    { borderRadius: [from, to] },
    {
      pseudoElement: `::view-transition-group(${name})`,
      duration: SHARE.duration * 1000,
      easing: `cubic-bezier(${SHARE.ease.join(',')})`,
      fill: 'both',
    },
  );
  const transition = (
    document as Document & { activeViewTransition?: ViewTransition | null }
  ).activeViewTransition;
  transition?.finished.finally(() => animation.cancel());
}

const middle = ({ top, bottom }: Frame) => `50% ${(top + bottom) / 2}px`;

export const EFFECTS: Record<
  Effect,
  (back: boolean, enter: Frame, exit: Frame) => EffectAnimation
> = {
  fade: () => ({
    enter: {
      opacity: [0, 1],
      filter: [blur.panel, 'blur(0px)'],
      transition: { duration: 0.3, ease: ease.out },
    },
    exit: {
      opacity: [1, 0],
      filter: ['blur(0px)', blur.panel],
      transition: { duration: 0.15, ease: ease.leave },
    },
  }),
  slide: (back) => {
    const from = back ? -SLIDE : SLIDE;
    return {
      enter: {
        opacity: [0, 1],
        transform: [`translateX(${from}px)`, 'none'],
        transition: { duration: 0.4, ease: ease.out },
      },
      exit: {
        opacity: [1, 0],
        transform: ['none', `translateX(${-from}px)`],
        transition: { duration: 0.2, ease: ease.leave },
      },
    };
  },
  push: (back) => {
    const from = back ? -100 : 100;
    return {
      enter: {
        transform: [`translateX(${from}%)`, 'none'],
        transition: { duration: 0.5, ease: ease.inOut },
      },
      exit: {
        transform: ['none', `translateX(${-from}%)`],
        transition: { duration: 0.5, ease: ease.inOut },
      },
    };
  },
  zoom: (_, enter, exit) => ({
    enter: {
      opacity: [0, 1],
      transform: ['scale(0.94)', 'none'],
      transformOrigin: [middle(enter), middle(enter)],
      transition: { duration: 0.4, ease: ease.out },
    },
    exit: {
      opacity: [1, 0],
      transform: ['none', 'scale(1.04)'],
      transformOrigin: [middle(exit), middle(exit)],
      transition: { duration: 0.2, ease: ease.leave },
    },
  }),
  iris: (_, { width, top, bottom, x, y }) => {
    const radius = Math.hypot(
      Math.max(x, width - x),
      Math.max(y - top, bottom - y),
    );
    return {
      enter: {
        clipPath: [
          `circle(0px at ${x}px ${y}px)`,
          `circle(${radius}px at ${x}px ${y}px)`,
        ],
        transition: { duration: 0.6, ease: ease.resize },
      },
      exit: still(0.6),
    };
  },
  wipe: (back) => ({
    enter: {
      clipPath: [back ? 'inset(0 100% 0 0)' : 'inset(0 0 0 100%)', 'inset(0)'],
      transition: { duration: 0.5, ease: ease.resize },
    },
    exit: {
      transform: ['none', `translateX(${back ? 8 : -8}%)`],
      transition: { duration: 0.5, ease: ease.resize },
    },
  }),
  bands: (back, enter) => ({
    enter: {
      clipPath: bandFrames(back, enter),
      transition: { duration: 0.7, ease: 'linear' },
    },
    exit: still(0.7),
  }),
  stack: (back, enter, exit) => {
    const distance = enter.bottom - enter.top;
    return {
      enter: {
        transform: [`translateY(${back ? -distance : distance}px)`, 'none'],
        transition: { duration: 0.5, ease: ease.resize },
      },
      exit: {
        transform: ['none', 'scale(0.94)'],
        transformOrigin: [middle(exit), middle(exit)],
        opacity: [1, 0.6],
        transition: { duration: 0.5, ease: ease.resize },
      },
    };
  },
  flow: (back) => {
    const from = back ? -30 : 30;
    return {
      enter: {
        opacity: [0, 1],
        transform: [`translateX(${from}%)`, 'none'],
        filter: ['blur(12px)', 'blur(0px)'],
        transition: { duration: 0.35, ease: ease.out },
      },
      exit: {
        opacity: [1, 0],
        transform: ['none', `translateX(${-from}%)`],
        filter: ['blur(0px)', 'blur(12px)'],
        transition: { duration: 0.25, ease: ease.leave },
      },
    };
  },
  chop: (back, { top, bottom }) => ({
    enter: {
      clipPath: back
        ? [
            `polygon(0% ${top}px, -20% ${top}px, 0% ${bottom}px, 0% ${bottom}px)`,
            `polygon(0% ${top}px, 120% ${top}px, 100% ${bottom}px, 0% ${bottom}px)`,
          ]
        : [
            `polygon(100% ${top}px, 100% ${top}px, 100% ${bottom}px, 120% ${bottom}px)`,
            `polygon(-20% ${top}px, 100% ${top}px, 100% ${bottom}px, 0% ${bottom}px)`,
          ],
      transition: { duration: 0.55, ease: ease.inOut },
    },
    exit: {
      transform: ['none', `translateX(${back ? 6 : -6}%)`],
      transition: { duration: 0.55, ease: ease.inOut },
    },
  }),
};

export function pickEffect(previous?: Effect): Effect {
  const choices = (Object.keys(EFFECTS) as Effect[]).filter(
    (name) => name !== previous,
  );
  return choices[Math.floor(Math.random() * choices.length)]!;
}

export function frameOf(element: HTMLElement, point?: { x: number; y: number }) {
  const rect = element.getBoundingClientRect();
  const top = Math.min(Math.max(0, -rect.top), rect.height);
  const bottom = Math.max(top, Math.min(rect.height, innerHeight - rect.top));
  return {
    width: rect.width,
    top,
    bottom,
    x: point ? point.x - rect.left : rect.width / 2,
    y: point ? point.y - rect.top : (top + bottom) / 2,
  };
}

export function backgroundOf(element: HTMLElement) {
  for (
    let node: HTMLElement | null = element;
    node;
    node = node.parentElement
  ) {
    const color = getComputedStyle(node).backgroundColor;
    if (color !== 'transparent' && !/rgba\(.*,\s*0\)$/.test(color))
      return color;
  }
  return 'canvas';
}

export function clipRadius(element: HTMLElement) {
  const own = getComputedStyle(element).borderRadius;
  if (own !== '0px') return own;
  let parent = element.parentElement;
  while (parent && getComputedStyle(parent).overflow === 'visible')
    parent = parent.parentElement;
  if (!parent) return '0px';
  const style = getComputedStyle(parent);
  const outer = parent.getBoundingClientRect();
  const rect = element.getBoundingClientRect();
  const top = parseFloat(style.borderTopWidth);
  const right = parseFloat(style.borderRightWidth);
  const bottom = parseFloat(style.borderBottomWidth);
  const left = parseFloat(style.borderLeftWidth);
  const touches = {
    top: rect.top - (outer.top + top) < 1,
    right: outer.right - right - rect.right < 1,
    bottom: outer.bottom - bottom - rect.bottom < 1,
    left: rect.left - (outer.left + left) < 1,
  };
  const corner = (radius: string, a: boolean, b: boolean, border: number) =>
    a && b ? `${Math.max(0, parseFloat(radius) - border)}px` : '0px';
  return [
    corner(
      style.borderTopLeftRadius,
      touches.top,
      touches.left,
      Math.max(top, left),
    ),
    corner(
      style.borderTopRightRadius,
      touches.top,
      touches.right,
      Math.max(top, right),
    ),
    corner(
      style.borderBottomRightRadius,
      touches.bottom,
      touches.right,
      Math.max(bottom, right),
    ),
    corner(
      style.borderBottomLeftRadius,
      touches.bottom,
      touches.left,
      Math.max(bottom, left),
    ),
  ].join(' ');
}

import type { Router } from 'vue-router'
import { startTransition } from 'motion-v'

/**
 * Runs each route change of `router` in a view transition, typed `nav-back`
 * when the history goes back to the entry before, else `nav-forward`, so
 * PageTransition animates it.
 */
export function routeTransitions(router: Router) {
  return router.beforeResolve((to, from) => {
    if (!from.matched.length || to.fullPath === from.fullPath)
      return
    // On a back navigation, the history already stands on the entry whose next one we leave.
    const back = router.options.history.state?.forward === from.fullPath
    return new Promise<void>((resolve) => {
      startTransition(
        () =>
          new Promise<void>((done) => {
            const off = router.afterEach(() => {
              off()
              done()
            })
            resolve()
          }),
        { types: [back ? 'nav-back' : 'nav-forward'] },
      )
    })
  })
}

import {
  computed,
  defineComponent,
  Fragment,
  getCurrentInstance,
  h,
  inject,
  onBeforeUnmount,
  onMounted,
  ref,
  type ComputedRef,
  type InjectionKey,
  type Ref,
} from 'vue';
import {
  createGeneratorEasing,
  generateLinearEasing,
  MotionConfig,
  spring as springGenerator,
  useMotionConfig,
  type Transition,
} from 'motion-v';

const ease = {
  out: [0.23, 1, 0.32, 1],
  soft: [0.215, 0.61, 0.355, 1],
  draw: [0, 0, 0.58, 1],
  inOut: [0.77, 0, 0.175, 1],
  away: [0.33, 0.17, 0.67, 0.5],
  in: [0.4, 0, 1, 1],
  drawer: [0.34, 1.2, 0.64, 1],
  arrive: [0.11, 0, 0.5, 0],
  color: [0.25, 0.1, 0.25, 1],
  leave: [0, 0, 0.58, 1],
  enter: [0.25, 0.1, 0.35, 1],
  resize: [0.4, 0, 0.1, 1],
  fill: [0.4, 0, 0.2, 1],
} as const;

const spring = {
  press: { type: 'spring', stiffness: 550, damping: 30, restSpeed: 10 },
  pop: { type: 'spring', stiffness: 400, damping: 29 },
  tooltip: { type: 'spring', stiffness: 400, damping: 31 },
  dialog: { type: 'spring', stiffness: 150, damping: 25 },
  toast: { type: 'spring', stiffness: 280, damping: 24 },
  selection: { type: 'spring', stiffness: 300, damping: 30 },
  highlight: { type: 'spring', stiffness: 500, damping: 40 },
  reflow: { type: 'spring', stiffness: 500, damping: 40 },
  handoff: { type: 'spring', stiffness: 450, damping: 43 },
  morph: { type: 'spring', stiffness: 660, damping: 52 },
  height: {
    type: 'spring',
    stiffness: 300,
    damping: 30,
    bounce: 0,
    restDelta: 0.01,
  },
  slide: { type: 'spring', stiffness: 300, damping: 35, restDelta: 0.01 },
  thumb: { type: 'spring', stiffness: 300, damping: 25 },
  slider: { type: 'spring', stiffness: 400, damping: 32 },
  bounce: { type: 'spring', stiffness: 200, damping: 16 },
  glyph: { type: 'spring', stiffness: 500, damping: 45 },
  checkPop: { type: 'spring', stiffness: 500, damping: 24 },
  entrance: { type: 'spring', stiffness: 200, damping: 20 },
  progress: {
    type: 'spring',
    stiffness: 300,
    damping: 35,
    restDelta: 0.01,
    restSpeed: 0.1,
  },
  number: { type: 'spring', stiffness: 90, damping: 50 },
} as const satisfies Record<string, Transition>;

const transition = {
  menu: { duration: 0.22, ease: ease.soft },
  overlay: { duration: 0.4, ease: ease.soft },
  dialogFade: { duration: 0.4, ease: ease.soft },
  fade: { duration: 0.2, ease: ease.out },
  color: { duration: 0.2, ease: ease.color },
  reveal: { duration: 0.3, ease: ease.out },
  disclosure: { duration: 0.35, ease: ease.soft },
  panelOut: { duration: 0.15, ease: ease.leave },
  panelIn: { duration: 0.3, ease: ease.enter },
  tooltipIn: { duration: 0.34, ease: ease.enter },
  tooltipOut: { duration: 0.13, ease: ease.leave },
  panelHeight: { duration: 0.45, ease: ease.resize },
  check: { duration: 0.3, delay: 0.2, ease: ease.draw },
  uncheck: { duration: 0.3, ease: ease.draw },
  fill: { duration: 0.3, ease: ease.fill },
  popOut: { duration: 0.15, ease: ease.out },
  swap: { duration: 0.15, ease: ease.out },
  spin: { duration: 0.3, ease: ease.out },
  handoffOut: { duration: 0.22, ease: ease.soft },
  handoffIn: { duration: 0.26, ease: ease.arrive },
  dismiss: { duration: 0.2, ease: ease.away },
  shake: { duration: 0.4, ease: ease.inOut },
  drawerOut: { duration: 0.16, ease: ease.in },
  drawer: { duration: 0.4, ease: ease.drawer },
  sheet: { duration: 0.4, ease: ease.soft },
  collapse: { duration: 0.28, ease: ease.inOut },
  collapseLabel: { duration: 0.14, ease: ease.out },
  instant: { duration: 0 },
} as const satisfies Record<string, Transition>;

const scale = {
  press: 0.97,
  choice: 0.985,
  tooltip: 0.7,
  popover: 0.8,
  menu: 0.9,
  dialog: 0.8,
  icon: 0.5,
  toast: 0.96,
  fill: 0.7,
  action: 0.9,
} as const;

const blur = {
  icon: 'blur(2px)',
  tooltip: 'blur(6px)',
  disclosure: 'blur(2px)',
  surface: 'blur(4px)',
  panel: 'blur(5px)',
} as const;

const rotate = {
  icon: 90,
} as const;

const shift = {
  handoff: 6,
  navigation: 24,
  tabs: 12,
  step: 24,
  tooltip: 40,
  shake: 3,
} as const;

const stagger: { readonly stack: number } = {
  stack: 0.03,
};

const TIME_KEYS = [
  'duration',
  'visualDuration',
  'delay',
  'repeatDelay',
  'delayChildren',
];

function scaleTransition<T extends Transition | undefined>(
  value: T,
  tempo: number,
): T {
  if (!value || tempo === 1 || typeof value !== 'object') return value;
  const scaled: Record<string, unknown> = {};
  for (const [key, part] of Object.entries(value)) {
    if (typeof part === 'number' && TIME_KEYS.includes(key))
      scaled[key] = part * tempo;
    else if (typeof part === 'number' && key === 'stiffness')
      scaled[key] = part / (tempo * tempo);
    else if (typeof part === 'number' && key === 'damping')
      scaled[key] = part / tempo;
    else if (part && typeof part === 'object' && !Array.isArray(part))
      scaled[key] = scaleTransition(part as Transition, tempo);
    else scaled[key] = part;
  }
  return scaled as T;
}

function createMotionTokens(tempo = 1) {
  const pace = <T extends Record<string, Transition>>(set: T): T =>
    tempo === 1
      ? set
      : (Object.fromEntries(
          Object.entries(set).map(([role, value]) => [
            role,
            scaleTransition(value, tempo),
          ]),
        ) as T);

  return {
    tempo,
    ease,
    scale,
    blur,
    rotate,
    shift,
    stagger:
      tempo === 1
        ? stagger
        : (Object.fromEntries(
            Object.entries(stagger).map(([role, delay]) => [
              role,
              delay * tempo,
            ]),
          ) as typeof stagger),
    spring: pace(spring),
    transition: pace(transition),
  } as const;
}

type MotionTokens = ReturnType<typeof createMotionTokens>;
type CheckAnimation = 'draw' | 'pop';
type ReducedMotion = 'user' | 'never' | 'always';

const motionTokens: MotionTokens = createMotionTokens();

const MotionTokensKey: InjectionKey<Ref<MotionTokens>> = Symbol(
  'AnimateUIMotionTokens',
);
const CheckAnimationKey: InjectionKey<Ref<CheckAnimation>> = Symbol(
  'AnimateUICheckAnimation',
);
const ReducedMotionKey: InjectionKey<Ref<ReducedMotion>> = Symbol(
  'AnimateUIReducedMotion',
);

function useMotionTokens(): Ref<MotionTokens> {
  return inject(MotionTokensKey, ref(motionTokens) as Ref<MotionTokens>);
}

/** Scales a transition by the provider's `tempo`. */
function useTempoTransition<T extends Transition | undefined>(
  value: () => T,
): ComputedRef<T> {
  const tokens = useMotionTokens();
  return computed(() => scaleTransition(value(), tokens.value.tempo));
}

function useCheckAnimation(own?: () => CheckAnimation | undefined) {
  const inherited = inject(CheckAnimationKey, ref<CheckAnimation>('draw'));
  return computed(() => own?.() ?? inherited.value);
}

function useReducedMotionSetting(): ComputedRef<ReducedMotion> {
  const own = inject(ReducedMotionKey, ref<ReducedMotion>('user'));
  const config = useMotionConfig();
  return computed(() =>
    config.value.reducedMotion === 'always' ? 'always' : own.value,
  );
}

type CssTiming = { duration: number; easing: string };

const CSS_EASINGS: Record<string, string> = {
  linear: 'linear',
  easeIn: 'cubic-bezier(0.42, 0, 1, 1)',
  easeOut: 'cubic-bezier(0, 0, 0.58, 1)',
  easeInOut: 'cubic-bezier(0.42, 0, 0.58, 1)',
  circIn: 'cubic-bezier(0, 0.65, 0.55, 1)',
  circOut: 'cubic-bezier(0.55, 0, 1, 0.45)',
  backIn: 'cubic-bezier(0.31, 0.01, 0.66, -0.59)',
  backOut: 'cubic-bezier(0.33, 1.53, 0.69, 0.99)',
};

const SPRING_KEYS = [
  'stiffness',
  'damping',
  'mass',
  'bounce',
  'visualDuration',
];

function toCssEase(curve: unknown): string {
  if (
    Array.isArray(curve) &&
    curve.length === 4 &&
    curve.every(Number.isFinite)
  )
    return `cubic-bezier(${curve.join(', ')})`;
  if (typeof curve === 'string') return CSS_EASINGS[curve] ?? 'ease';
  return CSS_EASINGS.easeInOut!;
}

function toCssTiming(motionTransition: Transition): CssTiming {
  const options = motionTransition as Record<string, unknown>;
  const isSpring =
    options.type === 'spring' || SPRING_KEYS.some((key) => key in options);

  if (isSpring) {
    const springOptions =
      typeof options.duration === 'number'
        ? { ...options, duration: options.duration * 1000 }
        : options;
    const { duration, ease: curve } = createGeneratorEasing(
      springOptions,
      100,
      springGenerator,
    );
    const ms = Math.round(duration * 1000);
    return { duration: ms, easing: generateLinearEasing(curve, ms) };
  }

  const seconds = typeof options.duration === 'number' ? options.duration : 0.3;
  return {
    duration: Math.round(seconds * 1000),
    easing: toCssEase(options.ease),
  };
}

const REDUCED_MOTION_QUERY = '(prefers-reduced-motion: reduce)';

// Once the app has mounted (hydrated), later components read the setting at once.
const appMounted = () =>
  Boolean(
    (
      getCurrentInstance()?.appContext.app as
        { _container?: unknown } | undefined
    )?._container,
  );

/** False on the server and while hydrating, then follows the OS setting. */
function useShouldReduceMotion(): ComputedRef<boolean> {
  const setting = useReducedMotionSetting();
  const prefersReduced = ref(
    appMounted() && window.matchMedia(REDUCED_MOTION_QUERY).matches,
  );
  let query: MediaQueryList | undefined;
  const update = () => {
    prefersReduced.value = query?.matches ?? false;
  };
  onMounted(() => {
    query = window.matchMedia(REDUCED_MOTION_QUERY);
    update();
    query.addEventListener('change', update);
  });
  onBeforeUnmount(() => query?.removeEventListener('change', update));
  return computed(() => {
    if (setting.value === 'never') return false;
    return setting.value === 'always' || prefersReduced.value;
  });
}

const RemountOnReduce = defineComponent({
  name: 'RemountOnReduce',
  setup(_, { slots }) {
    const reduce = useShouldReduceMotion();
    return () =>
      h(Fragment, { key: reduce.value ? 'reduce' : 'full' }, slots.default?.());
  },
});

const ReducedMotionConfig = defineComponent({
  name: 'ReducedMotionConfig',
  props: { remount: Boolean },
  setup(props, { slots }) {
    const reducedMotion = useReducedMotionSetting();
    return () =>
      h(MotionConfig, { reducedMotion: reducedMotion.value }, () =>
        props.remount ? h(RemountOnReduce, null, slots) : slots.default?.(),
      );
  },
});

export {
  createMotionTokens,
  motionTokens,
  MotionTokensKey,
  CheckAnimationKey,
  ReducedMotionKey,
  useMotionTokens,
  useCheckAnimation,
  ease,
  spring,
  transition,
  scale,
  blur,
  rotate,
  shift,
  stagger,
  ReducedMotionConfig,
  useShouldReduceMotion,
  useReducedMotionSetting,
  scaleTransition,
  toCssTiming,
  useTempoTransition,
  type CssTiming,
  type MotionTokens,
  type CheckAnimation,
  type ReducedMotion,
};
